package com.nova.payments; import com.nova.orders.OrderRecord; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="payments",uniqueConstraints=@UniqueConstraint(columnNames="razorpay_order_id")) public class PaymentRecord { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false) @JoinColumn(name="order_id",nullable=false,unique=true) private OrderRecord order; @Column(name="razorpay_order_id",nullable=false,unique=true) private String razorpayOrderId; @Column(name="razorpay_payment_id") private String razorpayPaymentId; @Column(nullable=false) private String status="CREATED"; private Instant updatedAt=Instant.now(); protected PaymentRecord(){} public PaymentRecord(OrderRecord order,String razorpayOrderId){this.order=order;this.razorpayOrderId=razorpayOrderId;} public Long getId(){return id;} public void setId(Long id){this.id=id;} public OrderRecord getOrder(){return order;} public String getRazorpayOrderId(){return razorpayOrderId;} public String getRazorpayPaymentId(){return razorpayPaymentId;} public String getStatus(){return status;} public Instant getUpdatedAt(){return updatedAt;} public void paid(String paymentId){razorpayPaymentId=paymentId;status="PAID";updatedAt=Instant.now();}}
